import{b as o,O as d,g as a,j as c}from"./chunks/framework.DSt9LnBW.js";const s=JSON.parse('{"title":"MVC与MVVM的区别","description":"MVC是一种架构思想，全称Model-View-Controller，即模型-视图-控制器，MVC是后端的开发思想，将数据从后端经过控制器层转向前端视图展示。","frontmatter":{"date":"2026-06-09T00:00:00.000Z","tags":["React","架构"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/frontend/mvc-vs-mvvm/index.md","filePath":"个人博客/前端/23.MVC与MVVM的区别.md","lastUpdated":1789534268000}'),l={name:"blog/frontend/mvc-vs-mvvm/index.md"};function i(V,e,M,r,t,p){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="mvc与mvvm的区别" tabindex="-1">MVC与MVVM的区别 <a class="header-anchor" href="#mvc与mvvm的区别" aria-label="Permalink to &quot;MVC与MVVM的区别&quot;">​</a></h1><h2 id="mvc" tabindex="-1">MVC <a class="header-anchor" href="#mvc" aria-label="Permalink to &quot;MVC&quot;">​</a></h2><p>MVC是一种架构思想，全称<code>Model-View-Controller</code>，即模型-视图-控制器，MVC是后端的开发思想，将数据从后端经过控制器层转向前端视图展示。</p><ul><li><code>View</code>：视图层 <code>ui</code>界面</li><li><code>Model</code>：模型 数据</li><li><code>Controller</code>：控制器 接受并处理用户请求通知<code>Model</code>改变，并将<code>Model</code>返回给 <code>View</code></li></ul><p><img src="https://op.yychuiyan.com/docs-blog/mvc-vs-mvvm-01.png" alt="MVC 中 Model、View、Controller 的关系"></p><h3 id="mvc-的优点" tabindex="-1">MVC 的优点 <a class="header-anchor" href="#mvc-的优点" aria-label="Permalink to &quot;MVC 的优点&quot;">​</a></h3><p>（1）耦合性低：视图层和业务层分离，这样允许更改视图层代码而不用重新编译模型和控制器代码，改变其中一个不会影响到其他两个，所以这种设计思想有良好的松耦合的构件。</p><p>（2）重用性高：MVC模式允许各种不同样式的视图来访问同一个服务的代码，因为多个视图能共享要给模型数据。</p><p>（3）生命周期成本低：MVC使开发和维护用户接口的技术含量降低。</p><p>（4）部署快：使用MVC模式开发时间相当大的缩减，它使程序员集中精力在业务逻辑上，视图与业务逻辑分开。</p><p>（5）可维护性高：分离视图层和业务层逻辑也是WEB应用更易于维护和修改。</p><p>（6）有利于软件工程化管理：由于不同的层各司其职，每一层不同的应用具有某些特性，有利于通过工程化、工程化管理程序代码，可以使用控制器来连接不同的模型和视图去完成客户的需求.控制器可以根据用户需求选择模型进行处理，然后选择视图处理结果显示给用户。</p><h2 id="mvvm" tabindex="-1">MVVM <a class="header-anchor" href="#mvvm" aria-label="Permalink to &quot;MVVM&quot;">​</a></h2><p>MVVM 是<code>Model-View-ViewModel</code>的缩写，它是一种基于前端开发的架构模式，其核心是提供对<code>View</code>和 <code>ViewModel</code> 的双向数据绑定，这使得<code>ViewModel</code>的状态改变可以自动传递给<code>View</code>，即所谓的数据双向绑定。</p><p>Vue.js 是一个提供了MVVM风格的双向数据绑定的Javascript 库，专注于<code>View</code>层。它的核心是 MVVM 中的 <code>VM</code>，也就是 <code>ViewModel</code>。<code>ViewModel</code>负责连接 <code>View</code> 和 <code>Model</code>，保证视图和数据的一致性，这种轻量级的架构让前端开发更加高效、便捷。</p><ul><li><code>Model</code>：数据模型，存放用于展示的数据，有的数据是写死的，大多数是从后端返回的数据</li><li><code>View</code>：视图，用于界面，在前端我们可以理解为Dom操作</li><li><code>ViewModel</code>：视图模型，可实现数据的双向绑定，连接<code>View</code>和<code>Model</code>的桥梁，当数据变化时，<code>ViewModel</code>够监听到数据的变化（通过Data Bindings），自动更新视图，而当用户操作视图，<code>ViewModel</code>也能监听到视图的变化（通过DOM Listeners），然后通知数据做改动，这就实现了数据的双向绑定</li></ul><p><img src="https://op.yychuiyan.com/docs-blog/mvc-vs-mvvm-02.png" alt="MVVM 中 View 与 Model 通过 ViewModel 双向绑定"></p><h3 id="mvvm-的优点" tabindex="-1">MVVM 的优点 <a class="header-anchor" href="#mvvm-的优点" aria-label="Permalink to &quot;MVVM 的优点&quot;">​</a></h3><p>（1）低耦合：视图<code>View</code>可以独立于<code>Model</code>变化和修改，一个<code>ViewModel</code>可以绑定到不同的<code>View</code>上，当<code>View</code>变化的时候<code>Model</code>可以不变，当<code>Model</code>变化的时候<code>View</code>也可以不变。</p><p>（2）可重用性：可以把一些视图逻辑放在<code>ViewModel</code>里面，让很多<code>view</code>重用这段视图逻辑。</p><p>（3）独立开发：开发人员可以专注业务逻辑和数据的开发，设计人员可以专注页面设计。</p><p>（4）可测试：界面向来比较难预测时，测试可针对<code>ViewModel</code>来写。</p><h2 id="mvc与mvvm的区别-1" tabindex="-1"><strong>MVC与MVVM的区别</strong> <a class="header-anchor" href="#mvc与mvvm的区别-1" aria-label="Permalink to &quot;**MVC与MVVM的区别**&quot;">​</a></h2><p>（1）都是一种设计思想；</p><p>（2）MVC后端用的多，而MVVM是前端设计思想；</p><p>（3）MVC是单向通信，数据模型必须通过<code>Controller</code>层进行承上启下。MVVM是将<code>View</code>和<code>Model</code>实现自动同步，当<code>Model</code>属性改变时，不用再自己手动操作Dom元素，提高页面渲染性能。</p><h2 id="扩展-为什么会有mvvm框架" tabindex="-1">扩展：为什么会有MVVM框架 <a class="header-anchor" href="#扩展-为什么会有mvvm框架" aria-label="Permalink to &quot;扩展：为什么会有MVVM框架&quot;">​</a></h2><p>在过去的10年中，我们已经把很多传统的服务端代码放到了浏览器中，这样就产生了成千上万行的javascript代码，它们连接了各式各样的HTML 和CSS文件，但缺乏正规的组织形式，这就是为什么越来越多的开发者使用javascript框架，比如：angular、react、vue。</p><p>浏览器的兼容性问题已经不再是前端的阻碍，前端的项目越来越大，项目的可维护性和扩展性、安全性等成了主要问题，当年为了解决浏览器兼容性问题，出现了很多类库，其中最典型的就是jquery，但是这类库没有实现对业务逻辑的分成，所以维护性和扩展性极差。</p><p>综上两方面原因，才有了MVVM模式一类框架的出现。比如vue，通过数据的双向绑定，极大了提高了开发效率。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>MVC 里 View 听 Controller；MVVM 用数据绑定把 View 和 Model 粘上，ViewModel 扛逻辑。前端项目变大之后，少写 DOM 操作换来的是绑定链本身也要维护。</p><hr><p>参考资料：</p><ul><li><a href="https://baijiahao.baidu.com/s?id=1771815700558512784&amp;wfr=spider&amp;for=pc" target="_blank" rel="noreferrer">MVC 与 MVVM 的区别（转载）</a></li></ul><hr>',36)])])}const n=o(l,[["render",i]]);export{s as __pageData,n as default};
